package bitbucket

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// User describes the account a token belongs to.
type User struct {
	Name string `json:"name"`
	Slug string `json:"slug"`
}

// WhoAmI resolves the account behind req's bearer token.
func (c *Client) WhoAmI(req *http.Request) (*User, error) {
	resp, err := c.http.Do(req)
	if err != nil {
		return nil, fmt.Errorf("whoami: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("whoami: status %d", resp.StatusCode)
	}
	var u User
	if err := json.NewDecoder(resp.Body).Decode(&u); err != nil {
		return nil, fmt.Errorf("whoami: decode: %w", err)
	}
	return &u, nil
}
